@pytest.mark.skip(reason="making progress on the other file first")
def test_block_extraction():
    # Your original payload
    for relation in frame_block_relation:
        payload =  relation["frame"] # """"""
        #payload = ""
        # print("=== Smart Meter Payload Extractor ===")
        # print("Processing Iskra AM550 HDLC frames...\n")
        
        extractor = SmartMeterPayloadExtractor()
        payload_results = extractor.process_hex_payload(payload)
        assert len(payload_results) == relation["blocks"]
            
        
        analyzer = OBISAnalyzer()
        block_results = analyzer.analyze_blocks(payload_results)
        assert len(block_results["energy_measurements"]) == relation["obis_results"]
        assert len(block_results["analyzed_blocks"]) == relation["blocks"]
        # Print summary
        extractor.print_summary()

        # Save results to file for further analysis
        
        import json
        with open('extracted_blocks.json', 'w') as f:
            json.dump(payload_results, f, indent=2)
        with open('extracted_information.json', 'w') as f:
            json.dump(block_results, f, indent=2)
        print(f"\nDetailed results saved to 'extracted_blocks.json'")
    


