def test_block_extraction3():
   
    extractor = SmartMeterPayloadExtractor()
    frameset = my_large_frameset.replace("\n","")
    frameset = frameset.replace(" ","")
    frameset = frameset.strip()
    
    payload_results = extractor.process_hex_payload(frameset)
    
    print(f"🔍 Total data blocks extracted: {len(payload_results)}")
    
    for i, payload in enumerate(payload_results):
        print(f"\n📋 Data Block {i+1}:")
        print(f"  Keys available: {list(payload.keys())}")
        
        if 'msb' in payload:
            print(f"  MSB: 0x{payload['msb']:02x}")
        if 'length' in payload:
            print(f"  Length: {payload['length']} bytes")
        if 'decryption_status' in payload:
            print(f"  Decryption Status: {payload['decryption_status']}")
        
        # Try to analyze the data if available
        if 'raw_data' in payload:
            analyzer = OBISAnalyzer()
            myres = analyzer.analyze_dlms_customer_interface(payload["raw_data"])
            print(f"  OBIS measurements found: {len(myres.get('energy_measurements', []))}")
    
    # Print summary
    extractor.print_summary()
    
    # Basic verification that we extracted some data
    assert len(payload_results) > 0, "Should extract at least one data block"
    print(f"\n✅ Successfully processed {len(payload_results)} data blocks from C code frameset!")
